"use client";

import { User } from "../types/user";
import { useRef, useEffect } from "react";

type Props = {
  user: User;
  formData: any;
  setFormData: React.Dispatch<React.SetStateAction<any>>;
  onClose: () => void;
  onSave: () => void;
  errors?: Record<string, string>;
  mode: "create" | "edit";
};

export default function EditUserModal({
  user,
  formData,
  setFormData,
  onClose,
  onSave,
  errors,
  mode,
}: Props) {
  const inputRef = useRef<HTMLInputElement | null>(null);
  const autocompleteRef = useRef<any>(null);

  useEffect(() => {
    if (!inputRef.current || !window.google?.maps?.places) return;

    // Use the new PlaceAutocompleteElement if available, otherwise fall back to Autocomplete
    if (window.google.maps.places.PlaceAutocompleteElement) {
      // Create PlaceAutocompleteElement for autocomplete suggestions
      const placeAutocomplete = new google.maps.places.PlaceAutocompleteElement();

      placeAutocomplete.addEventListener("gmp-placeselect", async (event: any) => {
        const place = event.place;

        if (place) {
          await place.fetchFields({
            fields: ["formattedAddress"],
          });

          setFormData((prev: any) => ({
            ...prev,
            address: place.formattedAddress || "",
          }));
        }
      });

      // Style the autocomplete to match our input
      if (inputRef.current.parentElement) {
        inputRef.current.parentElement.appendChild(placeAutocomplete);
        placeAutocomplete.style.position = "absolute";
        placeAutocomplete.style.width = "100%";
        placeAutocomplete.style.zIndex = "10";
      }

      autocompleteRef.current = placeAutocomplete;
    } else {
      // Fallback to old Autocomplete API
      const autocomplete = new google.maps.places.Autocomplete(inputRef.current, {
        fields: ["formatted_address"],
        types: ["address"],
      });

      autocomplete.addListener("place_changed", () => {
        const place = autocomplete.getPlace();
        setFormData((prev: any) => ({
          ...prev,
          address: place?.formatted_address || "",
        }));
      });

      autocompleteRef.current = autocomplete;
    }

    return () => {
      if (autocompleteRef.current && autocompleteRef.current.remove) {
        autocompleteRef.current.remove();
      }
    };
  }, []);

  const handleInputChange = (field: string, value: string) => {
    setFormData((prev: any) => ({
      ...prev,
      [field]: value,
    }));
  };

  return (
    <div className="fixed inset-0 bg-black/40 dark:bg-white/50 flex items-center justify-center p-6 z-50">
      <div className="w-full max-w-lg max-h-[90vh] overflow-y-auto bg-white dark:bg-gray-800 p-6 rounded-2xl shadow-xl space-y-3">

        <h2 className="text-xl font-semibold text-black dark:text-white">
          {mode === "create"
            ? "Create New User"
            : `Editing User #${user.id}`}
        </h2>

        {/* INPUT FIELDS */}
        {["firstName", "middleName", "lastName", "email", "phoneNumber"].map(
          (field) => (
            <div key={field} className="space-y-1">
              <div className="border rounded-xl border-gray-300 dark:border-violet-500/50 bg-white dark:bg-gray-700 focus-within:border-violet-500 focus-within:ring-1 focus-within:ring-violet-700 transition-all duration-200">
                <input
                  className="w-full p-2 rounded-xl bg-transparent text-black dark:text-white outline-none"
                  placeholder={field}
                  value={formData[field] || ""}
                  onChange={(e) =>
                    handleInputChange(field, e.target.value)
                  }
                />
              </div>

              {errors?.[field] && (
                <p className="text-red-500 text-sm">{errors[field]}</p>
              )}
            </div>
          )
        )}

        {/* ADDRESS (NEW GOOGLE PLACES WAY) */}
        <div className="space-y-1">
          <label className="text-sm font-medium text-gray-700 dark:text-gray-300">Address</label>
          <div ref={containerRef} className="border rounded-xl border-gray-300 dark:border-violet-500/50 bg-white dark:bg-gray-700 focus-within:border-violet-500 focus-within:ring-1 focus-within:ring-violet-700 transition-all duration-200 p-2">
            {/* PlaceAutocompleteElement will be inserted here */}
          </div>

          {errors?.address && (
            <p className="text-red-500 text-sm">{errors.address}</p>
          )}


        </div>

        {/* NOTES */}
        <div className="border rounded-xl border-gray-300 dark:border-violet-500/50 bg-white dark:bg-gray-700 focus-within:border-violet-500 focus-within:ring-1 focus-within:ring-violet-700 transition-all duration-200">
          <textarea
            className="w-full p-2 rounded-xl bg-transparent text-black dark:text-white outline-none resize-none"
            placeholder="Notes"
            value={formData.adminNotes || ""}
            onChange={(e) =>
              handleInputChange("adminNotes", e.target.value)
            }
          />
        </div>

        {/* BUTTONS */}
        <div className="flex justify-end gap-2 pt-2">
          <button
            onClick={onClose}
            className="px-4 py-2 rounded-xl border border-gray-300 dark:border-violet-700 text-black dark:text-white"
          >
            Cancel
          </button>

          <button
            onClick={onSave}
            className="px-4 py-2 rounded-xl bg-black dark:bg-violet-700 text-white"
          >
            Save
          </button>
        </div>
      </div>
    </div>
  );
}

